
(()=>{'use strict';const M=window.Matchsik,$=s=>document.querySelector(s);let session;try{session=JSON.parse(sessionStorage.getItem('matchsik_student_portal')||'null')}catch{}if(!session||Date.now()-Number(session.createdAt)>30*60*1000){location.replace('/my.html');return}const payload=session.data||{},items=payload.items||[];const lessons=items.flatMap(i=>(i.lessons||[]).map(l=>({...l,code:i.code||i.application?.code,application:i.application})));let month=new Date();function statusText(s){return({PAYMENT_PENDING:'입금 전',PAYMENT_REPORTED:'입금 확인 중',PAYMENT_REVIEW:'입금 확인 중',PAYMENT_CONFIRMED:'입금 확인 완료',CLASS_APPROVED:'수업 확정',CANCELLED:'취소',EXPIRED:'만료',REFUNDED:'환불 완료'}[s]||s||'확인 중')}function calendar(){const first=new Date(month.getFullYear(),month.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const cells=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ds=M.ymd(d),events=lessons.filter(l=>String(l.starts_at||'').slice(0,10)===ds);cells.push(`<div class="cal-day ${d.getMonth()!==month.getMonth()?'other':''}"><span class="cal-num">${d.getDate()}</span>${events.map(e=>`<span class="cal-event">${new Date(e.starts_at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'})} ${M.esc(e.application?.teacher_name||'수업')}</span>`).join('')}</div>`)}return `<div class="cal-head"><button class="btn btn-secondary" data-month="-1">‹</button><h2>${month.getFullYear()}년 ${month.getMonth()+1}월</h2><button class="btn btn-secondary" data-month="1">›</button></div><div class="cal-week">${['일','월','화','수','목','금','토'].map(x=>`<div>${x}</div>`).join('')}</div><div class="cal-days">${cells.join('')}</div>`}function render(){const profile=payload.profile||{name:session.identity.name,phoneMasked:M.phone(session.identity.phone).replace(/\d(?=\d{4})/g,'*')};$('#studentRoot').innerHTML=`<section class="portal-hero"><span class="eyebrow">MY CLASS</span><h1>${M.esc(profile.name||session.identity.name)}님의 수업</h1><p>${M.esc(profile.phoneMasked||'')} · 입금과 승인 상태에 따라 캘린더가 갱신됩니다.</p></section><section class="portal-panel"><div class="trust-grid">${items.map(i=>{const a=i.application||{};return `<article class="trust-card"><span class="status-pill">${statusText(a.status)}</span><b style="margin-top:10px">${M.esc(a.cert)} ${M.esc(a.course)}</b><span>${M.esc(a.teacher_name||'강사 배정 중')} · ${a.sessions||0}회 · ${M.money(a.amount)}</span></article>`}).join('')||'<div class="notice">신청 정보가 없습니다.</div>'}</div></section><section class="portal-panel" style="margin-top:18px"><div id="calendar">${calendar()}</div></section><section class="portal-panel" style="margin:18px 0 60px"><h2>수업 일정표</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>날짜</th><th>시간</th><th>강사</th><th>상태</th></tr></thead><tbody>${lessons.map(l=>`<tr><td>${String(l.starts_at).slice(0,10)}</td><td>${new Date(l.starts_at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'})}</td><td>${M.esc(l.application?.teacher_name||'')}</td><td>수업 확정</td></tr>`).join('')||'<tr><td colspan="4">아직 확정된 수업이 없습니다.</td></tr>'}</tbody></table></div></section>`;document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);render()})}$('#logout').onclick=()=>{sessionStorage.removeItem('matchsik_student_portal');location.replace('/my.html')};render()})();
